		methods: {
			accountBookData: function(type) {
				return new Promise((resolve, reject) => {
					if (uni.getStorageSync("token") && uni.getStorageSync("userInfo")) {
						let userInfo = JSON.parse(uni.getStorageSync("userInfo"));
						// 获取账本信息
						uni.request({
							url: `${this.globalData.baseURL}/api/v1/account-book?user_id=${
              userInfo.id
            }&sort_type=${type ? type : 0}`,
							method: "GET",
							success: (res) => {
								if (res.data?.account_books?.length) {
									this.globalData.accountBookList = res.data.account_books;
								} else {
									this.globalData.accountBookList = [];
								}
								resolve(res.data);
							},
							fail: (err) => {
								reject(err);
							},
						});
					} else {
						reject("请登录");
					}
				});
			},
			getUserData: function(id) {
				return new Promise((resolve, reject) => {
					uni.request({
						url: `${this.globalData.baseURL}/api/v1/user?id=${id}`,
						method: "GET",
						success: (res) => {
							resolve(res.data); // 或你需要的字段
						},
						fail: (err) => {
							reject(err);
						},
					});
				});
			},
			userInfoData: function() {
				return new Promise((resolve, reject) => {
					if (uni.getStorageSync("token") && uni.getStorageSync("userInfo")) {
						let userInfo = JSON.parse(uni.getStorageSync("userInfo"));
						// 获取账本信息
						uni.request({
							url: `${this.globalData.baseURL}/api/v1/user?id=${userInfo.id}`,
							method: "GET",
							success: (res) => {
								if (res.data?.message && res.data?.message) {
									uni.showToast({
										title: "用户不存在",
										icon: "none",
									});
									reject("用户不存在");
								} else {
									uni.setStorageSync("token", res.data.phone_number);
									uni.setStorageSync("userInfo", JSON.stringify(res.data));
									uni.setStorageSync("userName", res.data.name);
									uni.setStorageSync("phone_number", res.data.phone_number);
									if (res.data?.friend?.length) {
										// 使用 map 生成所有请求 Promise
										const promiseList = res.data.friend.map((id) =>
											this.getUserData(id)
										);
										// 使用 Promise.all 等待所有请求完成
										Promise.all(promiseList)
											.then((results) => {
												this.globalData.userList = results;
												resolve(results);
											})
											.catch((err) => {
												this.globalData.userList = [];
												resolve([]);
											});
									} else {
										resolve([]);
									}
								}
							},
							fail: (err) => {
								reject(err);
							},
						});
					} else {
						reject("请登录");
					}
				});
			},
			iconInfoData: function() {
				return new Promise((resolve, reject) => {
					console.log("进来了啊");
					if (uni.getStorageSync("token") && uni.getStorageSync("userInfo")) {
						let userInfo = JSON.parse(uni.getStorageSync("userInfo"));

						uni.request({
							url: `${this.globalData.baseURL}/api/v1/category?user_id=${userInfo.id}`,
							method: "GET",
							success: (res) => {
								this.globalData.iconData = res.data;
								resolve(res.data); // 或你需要的字段
							},
							fail: (err) => {
								this.globalData.iconData = [];
								reject(err);
							},
						});
					} else {
